`timescale 1ns/1ps
module tb;
  reg clk = 0;
  always #5 clk = ~clk;
  reg [63:0] data = 64'h1122334455667788;
  integer offset = 64;
  integer i;
  reg [0:95] direct4 = 0, bounded4 = 0;
  reg [0:103] direct5 = 0, bounded5 = 0;
  reg [0:87] direct3 = 0, bounded3 = 0;
  initial begin
    @(posedge clk);
    direct4[offset +: 64] <= data;
    direct5[offset +: 64] <= data;
    direct3[offset +: 64] <= data;
    for (i=0; i<8; i=i+1) begin
      if (offset+i*8 < 96) bounded4[offset+i*8 +: 8] <= data[63-i*8 -: 8];
      if (offset+i*8 < 104) bounded5[offset+i*8 +: 8] <= data[63-i*8 -: 8];
      if (offset+i*8 < 88) bounded3[offset+i*8 +: 8] <= data[63-i*8 -: 8];
    end
    #1;
    $display("TAIL4 direct=%h bounded=%h expected=11223344", direct4[64+:32], bounded4[64+:32]);
    $display("TAIL5 direct=%h bounded=%h expected=1122334455", direct5[64+:40], bounded5[64+:40]);
    $display("TAIL3 direct=%h bounded=%h expected=112233", direct3[64+:24], bounded3[64+:24]);
    $display("READ4 direct=%h expected_high=11223344", bounded4[offset+:64]);
    $display("READ5 direct=%h expected_high=1122334455", bounded5[offset+:64]);
    $display("READ3 direct=%h expected_high=112233", bounded3[offset+:64]);
    $finish;
  end
endmodule
